// Define your compile switches in here.// Note: For use with Source Sync do not leave this file blank or it won't get copied over to// your Windows machine.// EXPORT_MA is not defined anywhere - so force it to be defined.#ifndef qExportSymbols_MA	#define qExportSymbols_MA 0#endif// еее [MEB] 08/26/97 - Define some things for Windoze in this file temporarily#if qMSWindows		// Turn off grayscale appearance because it doesn't compile	#define qGrayscaleAppearance 0		// Include ConditionalMacros_AC.h so various q-switches are set correctly	#ifndef __ConditionalMacros_AC__	#include "ConditionalMacros_AC.h"	#endif				#ifndef qSharedLibrary_MA	#define qSharedLibrary_MA 0	#endif			#if qSharedLibrary_MA		#if qExportSymbols_MA			#define EXPORT_MA __declspec(dllexport)			#define EXPORT_CLASS_MA(theClass) class __declspec(dllexport) theClass;		#else			#define EXPORT_MA __declspec(dllimport)			#define EXPORT_CLASS_MA(theClass) class __declspec(dllimport) theClass;		#endif	#else		#define EXPORT_MA		#define EXPORT_CLASS_MA(theClass)	#endif#else	#ifndef qSharedLibrary_MA	#define qSharedLibrary_MA 0	#endif			#if qSharedLibrary_MA && !defined(__GNUC__)		#if qExportSymbols_MA			#define EXPORT_MA __declspec(export)			#define EXPORT_CLASS_MA(theClass) class __declspec(export) theClass;		#else			#define EXPORT_MA __declspec(import)			#define EXPORT_CLASS_MA(theClass) class __declspec(import) theClass;		#endif	#else		#define EXPORT_MA		#define EXPORT_CLASS_MA(theClass)	#endif#endif	// qMSWindows// *** We need a ConditionalMacros_MA.h where this stuff goes.